def solve_n_queens(n, fixed_positions):
    board = [-1] * n
    for row, col in fixed_positions.items():
        board[row] = col

    def is_safe(row, col):
        for i in range(n):
            if board[i] != -1:
                if i == row: continue
                if board[i] == col: return False
                if abs(board[i] - col) == abs(i - row): return False
        return True

    def backtrack(row):
        if row == n:
            return True

        if board[row] != -1:
            if is_safe(row, board[row]):
                return backtrack(row + 1)
            else:
                return False

        for col in range(n):
            if is_safe(row, col):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False

    if backtrack(0):
        return board
    else:
        return None

fixed = {11: 8, 16: 14, 18: 11, 21: 13}
solution = solve_n_queens(22, fixed)
print(solution)
